css:
:scope { width: min(100%, 1200px); margin-inline: auto; }
.gx { display: grid; grid-template-columns: repeat(24, minmax(0, 1fr)); grid-auto-rows: minmax(8px, auto); column-gap: 0; }
.gx__i { position: relative; z-index: 1; margin: 0; min-width: 0; overflow-wrap: break-word; }
.gx__i p { margin: 0; }
.gx__p { z-index: 0; }
.gx__img picture, .gx__img img { display: block; width: 100%; height: 100%; object-fit: cover; }
.gx__i1 { grid-column: 1 / span 24; grid-row: 1 / span 2; font-family: var(--os-font-label); font-size: 12px; font-weight: 400; line-height: 1.3; letter-spacing: 0.3em; text-transform: uppercase; color: var(--os-color-text-muted); }
.gx__i2 { grid-column: 1 / span 7; grid-row: 10 / span 5; font-family: var(--os-font-heading); font-size: 30px; font-weight: 500; line-height: 1.25; letter-spacing: 0em; color: var(--os-color-heading); }
.gx__i3 { grid-column: 9 / span 7; grid-row: 10 / span 9; font-family: var(--os-font-heading); font-size: 30px; font-weight: 500; line-height: 1.25; letter-spacing: 0em; color: var(--os-color-heading); }
.gx__i4 { grid-column: 17 / span 7; grid-row: 10 / span 5; font-family: var(--os-font-heading); font-size: 30px; font-weight: 500; line-height: 1.25; letter-spacing: 0em; color: var(--os-color-heading); }
.gx__i5 { grid-column: 1 / span 7; grid-row: 17 / span 8; font-family: var(--os-font-body); font-size: 21px; font-weight: 400; line-height: 1.5; letter-spacing: 0em; color: var(--os-color-text-muted); }
.gx__i6 { grid-column: 17 / span 7; grid-row: 17 / span 8; font-family: var(--os-font-body); font-size: 21px; font-weight: 400; line-height: 1.5; letter-spacing: 0em; color: var(--os-color-text-muted); }
.gx__i7 { grid-column: 9 / span 7; grid-row: 22 / span 8; font-family: var(--os-font-body); font-size: 21px; font-weight: 400; line-height: 1.5; letter-spacing: 0em; color: var(--os-color-text-muted); }
.gx__i8 { grid-column: 1 / span 7; grid-row: 34 / span 9; font-family: var(--os-font-heading); font-size: 30px; font-weight: 500; line-height: 1.25; letter-spacing: 0em; color: var(--os-color-heading); }
.gx__i9 { grid-column: 1 / span 7; grid-row: 46 / span 8; font-family: var(--os-font-body); font-size: 21px; font-weight: 400; line-height: 1.5; letter-spacing: 0em; color: var(--os-color-text-muted); }
@media (max-width: 767px) {
  .gx { display: flex; flex-direction: column; gap: var(--os-space-sm); }
  .gx__i1 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i2 { font-family: var(--os-font-heading); font-size: 24px; }
  .gx__i3 { font-family: var(--os-font-heading); font-size: 24px; }
  .gx__i4 { font-family: var(--os-font-heading); font-size: 24px; }
  .gx__i5 { font-family: var(--os-font-body); font-size: 17px; }
  .gx__i6 { font-family: var(--os-font-body); font-size: 17px; }
  .gx__i7 { font-family: var(--os-font-body); font-size: 17px; }
  .gx__i8 { font-family: var(--os-font-heading); font-size: 24px; }
  .gx__i9 { font-family: var(--os-font-body); font-size: 17px; }
}
